import React, { createContext, useContext, useState, useRef } from 'react';
import { DUMMY_RESOURCES } from '../data/dummyData';

const AppContext = createContext();

const API = 'http://localhost:5000/api';

export function AppProvider({ children }) {

  // ── State ──────────────────────────────────────────────────
  const [page, setPage]                       = useState('landing');
  const [user, setUser]                       = useState(null);
  const [dark, setDark]                       = useState(true);
  const [toasts, setToasts]                   = useState([]);
  const [selectedCollege, setSelectedCollege] = useState(null);
  const [resources, setResources]             = useState(DUMMY_RESOURCES);
  const [users, setUsers]                     = useState([]);
  const [routineDone, setRoutineDone]         = useState({});
  const toastId = useRef(0);

  // ── Toast — defined FIRST so all functions below can use it ──
  const toast = (msg, type = 'success') => {
    const id = ++toastId.current;
    setToasts((prev) => [...prev, { id, msg, type }]);
    setTimeout(() => setToasts((prev) => prev.filter((t) => t.id !== id)), 3500);
  };

  const removeToast = (id) => {
    setToasts((prev) => prev.filter((t) => t.id !== id));
  };

  // ── LOGIN — calls MongoDB backend ──────────────────────────
  const login = async (email, password) => {
    try {
      const res = await fetch(`${API}/auth/login`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, password }),
      });
      const data = await res.json();

      if (!res.ok) {
        toast(data.message || 'Invalid email or password', 'error');
        return false;
      }

      localStorage.setItem('token', data.token);
      setUser(data.user);
      setPage('dashboard');
      toast(`Welcome back, ${data.user.name.split(' ')[0]}! 👋`);
      return true;

    } catch (err) {
      toast('Cannot connect to server. Is backend running?', 'error');
      return false;
    }
  };

  // ── REGISTER — calls MongoDB backend ───────────────────────
  const register = async (formData) => {
    try {
      const res = await fetch(`${API}/auth/register`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(formData),
      });
      const data = await res.json();

      if (!res.ok) {
        toast(data.message || 'Registration failed', 'error');
        return false;
      }

      localStorage.setItem('token', data.token);
      setUser(data.user);
      setPage('dashboard');
      toast(`Account created! Welcome, ${data.user.name.split(' ')[0]}! 🎉`);
      return true;

    } catch (err) {
      toast('Cannot connect to server. Is backend running?', 'error');
      return false;
    }
  };

  // ── LOGOUT ─────────────────────────────────────────────────
  const logout = () => {
    localStorage.removeItem('token');
    setUser(null);
    setPage('landing');
    setSelectedCollege(null);
    toast('Logged out successfully');
  };

  // ── ADD RESOURCE — calls MongoDB backend ───────────────────
  const addResource = async (resData) => {
    try {
      const token = localStorage.getItem('token');
      const res = await fetch(`${API}/resources`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`,
        },
        body: JSON.stringify(resData),
      });
      const data = await res.json();

      if (!res.ok) {
        toast(data.message || 'Upload failed', 'error');
        return false;
      }

      setResources((prev) => [data, ...prev]);
      toast('Resource uploaded successfully! 📚');
      return true;

    } catch (err) {
      // Fallback — save locally if server not available
      setResources((prev) => [
        ...prev,
        {
          ...resData,
          id:         prev.length + 1,
          date:       new Date().toISOString().slice(0, 10),
          downloads:  0,
          views:      0,
          registered: 0,
        },
      ]);
      toast('Resource uploaded successfully! 📚');
      return true;
    }
  };

  // ── FETCH ALL USERS — admin only ───────────────────────────
  const fetchUsers = async () => {
    try {
      const token = localStorage.getItem('token');
      const res = await fetch(`${API}/users`, {
        headers: { 'Authorization': `Bearer ${token}` },
      });
      const data = await res.json();
      if (res.ok) setUsers(data);
    } catch (err) {
      toast('Could not fetch users', 'error');
    }
  };

  // ── REMOVE USER — admin only ───────────────────────────────
  const removeUser = async (id) => {
    try {
      const token = localStorage.getItem('token');
      const res = await fetch(`${API}/users/${id}`, {
        method: 'DELETE',
        headers: { 'Authorization': `Bearer ${token}` },
      });
      const data = await res.json();

      if (!res.ok) {
        toast(data.message || 'Could not remove user', 'error');
        return;
      }

      setUsers((prev) => prev.filter((u) => u._id !== id && u.id !== id));
      toast('User removed successfully', 'warning');

    } catch (err) {
      toast('Could not remove user', 'error');
    }
  };

  // ── Context value ──────────────────────────────────────────
  const value = {
    page,
    setPage,
    user,
    setUser,
    dark,
    setDark,
    toast,
    toasts,
    removeToast,
    login,
    register,
    logout,
    selectedCollege,
    setSelectedCollege,
    resources,
    setResources,
    addResource,
    users,
    setUsers,
    fetchUsers,
    removeUser,
    routineDone,
    setRoutineDone,
  };

  return (
    <AppContext.Provider value={value}>
      {children}
    </AppContext.Provider>
  );
}

export function useApp() {
  const ctx = useContext(AppContext);
  if (!ctx) throw new Error('useApp must be used inside AppProvider');
  return ctx;
}
